import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [h, w] = lines[0].split(" ").map(Number);
const grid = lines.slice(1, h + 1);
const MOD = 1_000_000_007;

// dp[x] = 今の行の x 列目にたどり着く経路の数（1 行ぶんを使い回す）
const dp = new Array(w).fill(0);
dp[0] = 1;
for (let y = 0; y < h; y++) {
  for (let x = 0; x < w; x++) {
    if (grid[y][x] === "#") dp[x] = 0;
    else if (x > 0) dp[x] = (dp[x] + dp[x - 1]) % MOD; // 上から + 左から
  }
}
console.log(dp[w - 1]);
